import os,sys,json,pathlib,platform,resource,importlib.metadata,datetime,shutil
def read(p):
 try:return pathlib.Path(p).read_text()
 except (OSError,UnicodeError) as e:return {'unavailable':type(e).__name__,'message':str(e)}
status=read('/proc/self/status')
status_map=dict(x.split(':',1) for x in status.splitlines() if ':' in x)
cg={name:read('/sys/fs/cgroup/'+name) for name in [
'cgroup.type','cgroup.controllers','cpu.max','cpu.max.burst','cpu.stat',
'cpuset.cpus','cpuset.cpus.effective','cpuset.mems.effective',
'memory.max','memory.high','memory.current','memory.peak','memory.swap.max',
'memory.swap.current','memory.events','memory.stat']}
topology={}
for cpu in [0,2,8]:
 topology[str(cpu)]={name:read('/sys/devices/system/cpu/cpu'+str(cpu)+'/topology/'+name) for name in ['physical_package_id','core_id','thread_siblings_list','core_cpus_list']}
versions={}
for name in ['numpy','scipy','matplotlib','threadpoolctl','mpmath']:
 try:versions[name]=importlib.metadata.version(name)
 except importlib.metadata.PackageNotFoundError:versions[name]=None
envnames=['OMP_NUM_THREADS','OMP_DYNAMIC','OMP_NESTED','OMP_MAX_ACTIVE_LEVELS','OPENBLAS_NUM_THREADS','MKL_NUM_THREADS','BLIS_NUM_THREADS','VECLIB_MAXIMUM_THREADS','NUMEXPR_NUM_THREADS','MALLOC_ARENA_MAX']
out={'observed_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),
'probe_scope':'One read-only C4 environment observation; no scientific imports, test, limit/affinity changes, lease creation or remote mutation.',
'pid':os.getpid(),'python':{'executable':sys.executable,'version':sys.version,'package_metadata_only':versions},
'kernel':platform.uname()._asdict(),'cpu_count_reported':os.cpu_count(),
'affinity':sorted(os.sched_getaffinity(0)),
'proc_self_status':status,
'proc_self_cgroup':read('/proc/self/cgroup'),
'cgroup_mounts':[x for x in read('/proc/self/mountinfo').splitlines() if ' - cgroup' in x],
'proc_meminfo':read('/proc/meminfo'),'proc_loadavg':read('/proc/loadavg'),
'cgroup':cg,'planned_cpu_topology':topology,
'process_limits':{'RLIMIT_AS':resource.getrlimit(resource.RLIMIT_AS),'RLIMIT_CPU':resource.getrlimit(resource.RLIMIT_CPU)},
'selected_thread_environment':{n:os.environ.get(n) for n in envnames},
'tool_paths':{n:shutil.which(n) for n in ['python','python3','git','mpirun','mpiexec','gfortran','gcc']},
'current_planned_limits_applied_by_probe':False,'scientific_runs':0,'tests':0,'implementation_files_written':0,'processes_killed':0,'remote_mutations':0}
print(json.dumps(out,ensure_ascii=False))
